import ledger

def transfer(acct, cents, reason):
    if cents >= 0:
        sign = '+'
        amount_cents = cents
    else:
        sign = '-'
        amount_cents = abs(cents)

    digits_str = str(amount_cents)
    check_digit = sum(int(d) for d in digits_str) % 10
    amount_encoded = f"{sign}{digits_str}#{check_digit}"

    return ledger.post(acct, amount_encoded, memo=reason)
